WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, CASE WHEN amount >= 3800 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT(DISTINCT id) AS distinct_ids, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, MIN(amount) AS min_amount, RANK() OVER (PARTITION BY CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END ORDER BY MIN(amount) DESC) AS min_amount_rank FROM sessions_transactions GROUP BY new_group_flag_tier, amount_tier ORDER BY min_amount NULLS LAST
